// Pure data-world helpers shared by the provider, the shell and tests. No React here.
import type { BundleIndexEntry, RunBundle } from "../../../core/src/schema";
import type { Certificate } from "../../../core/src/schema";
import type { CatalogOrigin as DataSource } from "../data";

/**
 * Live     = the data layer is in live mode (a local `notary serve` answered /api/health) and the selected run is real.
 * Recorded = real published bundles from static files.
 * Fixture  = the selected run is fixture data (bundle.sample), wherever it came from.
 */
export type DataMode = "live" | "recorded" | "fixture";

export function resolveDataMode(
  source: DataSource,
  selected?: Pick<BundleIndexEntry, "sample">,
): DataMode {
  if (selected?.sample) return "fixture";
  return source === "api" ? "live" : "recorded";
}

/**
 * `?fixtures=1`: the development-only view of the fixture runs (bundles/fixture, sample: true).
 * Without it the dashboard and the landing show real runs only, and an empty state when none is
 * published; with it they show fixture runs only, under the fixture disclosure. Never both at once.
 */
export const FIXTURES_PARAM = "fixtures";

/** True when a query string (or URLSearchParams) asks for the fixture view. */
export function fixturesRequested(search: string | URLSearchParams | null | undefined): boolean {
  if (!search) return false;
  const params = typeof search === "string" ? new URLSearchParams(search) : search;
  return params.get(FIXTURES_PARAM) === "1";
}

/** The fixture flag of the page the browser is on (false outside a browser). */
export const fixturesInLocation = (): boolean => fixturesRequested(globalThis.location?.search);

/**
 * The runs a view may show. Default: real runs only (live ones still running included). With the
 * fixture flag: finished fixture runs only — the fixture scenarios of bundles/fixture, never the
 * dashboard's synthetic SAMPLE bundle (kind/variant "sample", e.g. sample-42), which is its own data
 * world and would otherwise be counted next to the scenarios. A fixture run is never shown without
 * the flag, and a real run is never mixed into the fixture view.
 */
export function visibleRuns<T extends { sample?: boolean; state?: string; kind?: string; variant?: string }>(
  entries: readonly T[],
  fixtures: boolean,
): T[] {
  return entries.filter((e) => {
    const sample = e.state === "running" ? false : !!e.sample;
    if (!fixtures) return !sample;
    return sample && e.state !== "running" && !isSyntheticSample(e);
  });
}

/** The dashboard's synthetic SAMPLE bundle (not a fixture scenario, not a real run). */
export const isSyntheticSample = (e: { kind?: string; variant?: string }) => e.kind === "sample" || e.variant === "sample";

// --------------------------------------------------------------------------- replays

/**
 * Replays (bundle.mode === "replay") re-serve a recorded run's cassettes: no new tool calls, no new
 * spend. They are always labelled as such and listed after the live recordings.
 */
export const isReplayRun = (e: { mode?: string } | undefined): boolean => e?.mode === "replay";

/** What a replay's spend cell says instead of credits/USD (the original run holds the real spend). */
export const REPLAY_SPEND_TEXT = "Re-served from the recording — no new spend";

/**
 * The run a replay reproduces, read from its verified bundle (`replayOf`). Undefined for live runs
 * and when the bundle is not loaded (the label then says just "Replay"; nothing is guessed from ids).
 */
export function replayOfRun(
  e: { runId: string; mode?: string } | undefined,
  bundles: readonly Pick<RunBundle, "runId" | "replayOf">[] = [],
): string | undefined {
  if (!e || !isReplayRun(e)) return undefined;
  const own = "replayOf" in e ? (e as { replayOf?: string }).replayOf : undefined;
  return own ?? bundles.find((b) => b.runId === e.runId)?.replayOf;
}

/** "Replay of <original>" (or "Replay" when the original is unknown); undefined for live runs. */
export function replayBadge(
  e: { runId: string; mode?: string } | undefined,
  bundles: readonly Pick<RunBundle, "runId" | "replayOf">[] = [],
): string | undefined {
  if (!e || !isReplayRun(e)) return undefined;
  const of = replayOfRun(e, bundles);
  return of ? `Replay of ${of}` : "Replay";
}

/** Live recordings first (newest first), then replays (newest first). Running runs count as live. */
export function liveFirst<T extends { mode?: string; startedAt: string }>(entries: readonly T[]): T[] {
  const sorted = [...entries].sort((a, b) => b.startedAt.localeCompare(a.startedAt));
  return [...sorted.filter((e) => !isReplayRun(e)), ...sorted.filter((e) => isReplayRun(e))];
}

/** The empty state's next step when no real run is published. */
export const NO_RUNS_COMMANDS = ["pnpm notary notarize --tool crustdata", "pnpm notary export"] as const;

export const MODE_LABEL: Record<DataMode, string> = {
  live: "Live",
  recorded: "Recorded",
  fixture: "Fixture",
};

export type RunGroup = {
  kind: "live" | "recorded" | "fixture";
  label: string;
  runs: BundleIndexEntry[];
};

/**
 * Run picker sections: real runs first, then recorded fixtures. Fixture and real runs are never in
 * the same section. Within a section, live recordings come before replays. Empty sections are dropped.
 */
export function groupRuns(
  entries: BundleIndexEntry[],
  source: DataSource,
): RunGroup[] {
  // Live recordings before their replays, newest first within each.
  const sorted = liveFirst(entries);
  const real = sorted.filter((e) => !e.sample);
  const fixture = sorted.filter((e) => e.sample);
  const groups: RunGroup[] = [
    source === "api"
      ? { kind: "live", label: "Live runs", runs: real }
      : { kind: "recorded", label: "Recorded runs", runs: real },
    {
      kind: "fixture",
      label: "Fixture runs",
      runs: fixture,
    },
  ];
  return groups.filter((g) => g.runs.length > 0);
}

/**
 * Default selection, in order: a guarded queue run; else the newest LIVE run that recorded work
 * (probes or decisions, when the caller passes bundles that carry them); else the newest live run;
 * replays only when no live run exists (a replay re-serves cassettes and is never the first thing
 * shown). Real data before fixture data. Pass verified bundles once they are loaded: index entries
 * alone carry no probe/decision counts, so they can only rank by kind and recency.
 */
export function defaultRunId(
  entries: (Pick<BundleIndexEntry, "runId" | "sample" | "kind" | "variant" | "startedAt" | "mode"> & {
    probes?: readonly unknown[];
    decisions?: readonly unknown[];
  })[],
): string | undefined {
  const sorted = [...entries].sort((a, b) => b.startedAt.localeCompare(a.startedAt));
  const real = sorted.some((e) => !e.sample) ? sorted.filter((e) => !e.sample) : sorted;
  const live = real.filter((e) => !isReplayRun(e));
  const replays = real.filter((e) => isReplayRun(e));
  const guarded = (list: typeof real) => list.find((e) => e.kind === "run" && e.variant === "guarded");
  const worked = (e: (typeof real)[number]) => (e.probes?.length ?? 0) > 0 || (e.decisions?.length ?? 0) > 0;
  return (guarded(live) ?? live.find(worked) ?? live[0] ?? guarded(replays) ?? replays.find(worked) ?? replays[0])?.runId;
}

/** Same-cohort baseline candidates (fixture with fixture, real with real), never the run itself. */
export function baselineCandidates(
  bundle: RunBundle | undefined,
  bundles: RunBundle[],
): RunBundle[] {
  if (!bundle) return [];
  return bundles.filter(
    (b) => b.runId !== bundle.runId && b.sample === bundle.sample,
  );
}

export function pickBaseline(
  bundle: RunBundle | undefined,
  bundles: RunBundle[],
  requested: string | null,
): RunBundle | undefined {
  const candidates = baselineCandidates(bundle, bundles);
  return (
    candidates.find((b) => b.runId === requested) ??
    candidates.find(
      (b) =>
        b.kind === "run" &&
        b.variant === (bundle?.variant === "naive" ? "guarded" : "naive") &&
        // Fixture scenarios share a runId prefix; prefer the same scenario.
        scenarioKey(b.runId) === scenarioKey(bundle!.runId),
    ) ??
    candidates.find(
      (b) =>
        b.kind === "run" &&
        b.variant === (bundle?.variant === "naive" ? "guarded" : "naive"),
    ) ??
    candidates.find((b) => b.kind === bundle?.kind) ??
    candidates[0]
  );
}

/** Runs whose ids differ only in their trailing kind/variant share a key ("demo-change-api"). */
export function scenarioKey(runId: string): string {
  return runId.replace(/-(run|notarize)-[a-z]+$/, "");
}

export const heldCount = (bundle?: RunBundle) =>
  bundle ? bundle.decisions.filter((d) => d.status === "held").length : 0;

/**
 * `/app/...` path with the selected run (and optional extra params) in the query string. A query
 * already in `path` is kept (its `run` wins, so a record path can pin the run it belongs to).
 */
export function withRun(
  path: string,
  runId: string | undefined,
  extra: Record<string, string | undefined> = {},
): string {
  const [base, query = ""] = path.split("?", 2) as [string, string?];
  const own = new URLSearchParams(query);
  const params = new URLSearchParams();
  const run = own.get("run") ?? runId;
  if (run) params.set("run", run);
  for (const [k, v] of own) if (k !== "run") params.set(k, v);
  for (const [k, v] of Object.entries(extra)) if (v) params.set(k, v);
  // The development-only fixture view stays on while navigating inside the dashboard.
  if (fixturesInLocation() && !params.has(FIXTURES_PARAM)) params.set(FIXTURES_PARAM, "1");
  const q = params.toString();
  return q ? `${base}?${q}` : base;
}

/**
 * Where each record kind is shown. Decisions and probes live in the Run page's transcript
 * (`?decision=` / `?probe=` focus the record); beliefs and claims live with their certificates;
 * certificates have their own page.
 */
export const recordPath = {
  decision: (id: string) => keepView(`/app/run?decision=${encodeURIComponent(id)}`),
  probe: (id: string) => keepView(`/app/run?probe=${encodeURIComponent(id)}`),
  belief: (id: string) => keepView(`/app/certificates?belief=${encodeURIComponent(id)}`),
  certificate: (id: string) => keepView(`/app/certificates/${encodeURIComponent(id)}`),
  run: (id: string) => keepView(`/app/run?run=${encodeURIComponent(id)}`),
  report: (tool: string) => keepView(`/app/certificates?tool=${encodeURIComponent(tool)}`),
};

/** Keep the development-only fixture view (`?fixtures=1`) on a dashboard path when it is on now. */
export function keepView(path: string): string {
  if (!fixturesInLocation() || /[?&]fixtures=1(&|$)/.test(path)) return path;
  return `${path}${path.includes("?") ? "&" : "?"}${FIXTURES_PARAM}=1`;
}

export type PaletteEntry = {
  group: "Decisions" | "Probes" | "Beliefs" | "Certificates";
  id: string;
  label: string;
  hint: string;
  path: string;
};

/** Command-palette records for the selected run, all derived from its bundle (and its certificate world). */
export function paletteEntries(
  bundle: RunBundle | undefined,
  certificates: Certificate[] = [],
): PaletteEntry[] {
  if (!bundle) return [];
  const beliefs = new Map(
    [...bundle.beliefs.before, ...bundle.beliefs.after].map((b) => [b.id, b]),
  );
  return [
    ...bundle.decisions.map((d) => ({
      group: "Decisions" as const,
      id: d.id,
      label: `${d.requestId} · ${d.requestType.replaceAll("_", " ")}`,
      hint: `${d.status} · ${d.customerId}`,
      path: withRun(recordPath.decision(d.id), bundle.runId),
    })),
    ...bundle.probes.map((p) => ({
      group: "Probes" as const,
      id: p.id,
      label: `${p.id} · ${p.template.replaceAll("_", " ")}`,
      hint: `${p.verdict ?? "pending"} · ${p.claimId}`,
      path: withRun(recordPath.probe(p.id), bundle.runId),
    })),
    ...[...beliefs.values()].map((b) => ({
      group: "Beliefs" as const,
      id: b.id,
      label: b.statement,
      hint: `${b.status} · ${b.claimId}`,
      path: withRun(recordPath.belief(b.id), bundle.runId),
    })),
    ...certificates.map((c) => ({
      group: "Certificates" as const,
      id: c.id,
      label: `${c.claimId} · ${c.verdict}`,
      hint: `${c.status} · ${c.tool}`,
      path: withRun(recordPath.certificate(c.id), bundle.runId),
    })),
  ];
}
// The replay data the landing's showcase pieces render (hero mockup, feature mini-cards, chat):
// always the published, hash-verified files through the data layer's ReplaySource, so a live
// local server never changes what the marketing page shows. When the page already replays, its
// own source is reused (same cache, nothing fetched or hashed twice).
import type { BundleIndexEntry, RunBundle } from "../../../../core/src/schema";
import { finishedEntries, ReplaySource, type DataSource } from "../../data";
import { proofPair } from "../../landing-data";
import { fixturesInLocation } from "../../app/links";

let fallback: ReplaySource | undefined;

export function replayFor(source: DataSource): ReplaySource {
  if (source instanceof ReplaySource) return source;
  return (fallback ??= new ReplaySource());
}

export type ReplayPair = {
  entries: BundleIndexEntry[];
  naive?: RunBundle;
  guarded?: RunBundle;
  /**
   * The run the showcase pieces render (hero preview, certificate card, chat, how-it-works): the
   * guarded queue run when there is one, else the newest visible notarize run that probed
   * something (its certificate world is the same). Undefined only when no visible run exists.
   */
  preview?: RunBundle;
  sample: boolean;
};

const pairs = new WeakMap<ReplaySource, Promise<ReplayPair>>();

/**
 * The same pair the Proof section would pick, from the published files (memoized per source): real
 * runs only, or fixture runs only under the development-only ?fixtures=1. Empty when none exist.
 */
export function replayPair(replay: ReplaySource): Promise<ReplayPair> {
  let p = pairs.get(replay);
  if (!p) {
    p = (async () => {
      const entries = finishedEntries(await replay.listRuns());
      const pair = proofPair(entries, { fixtures: fixturesInLocation() });
      const guarded = pair.guarded ? await replay.getRun(pair.guarded.runId) : undefined;
      const naive = pair.naive ? await replay.getRun(pair.naive.runId) : undefined;
      let preview = guarded;
      if (!preview) {
        const notarize = entries
          .filter((e) => e.sample === pair.sample && e.kind === "notarize")
          .sort((a, b) => b.startedAt.localeCompare(a.startedAt));
        for (const e of notarize) {
          const b = await replay.getRun(e.runId);
          if (b.probes.length > 0) {
            preview = b;
            break;
          }
        }
      }
      return { entries, naive, guarded, preview, sample: pair.sample };
    })();
    p.catch(() => pairs.delete(replay));
    pairs.set(replay, p);
  }
  return p;
}
// The landing page (`/`): nav and hero (a dashboard preview built from the Run page's own rows)
// render first; Built with, How it works, Key features, Proof, Notary Chat, Pricing (only when
// public/economics.json lists priced plans), the closing CTA and the footer load as one lazy chunk.
// Copy follows the product-site rules in landing-data (BANNED_WORDS).
import { lazy, Suspense, useEffect, useRef, useState } from "react";
import { loadEconomicsPlan, useDataSource } from "./data";
import { pricingPlans, seeItWorkHref, type PricingPlan } from "./landing-data";
import { Hero } from "./components/landing/Hero";
import { Nav } from "./components/landing/Nav";
import "./landing.css";

const Below = lazy(() => import("./components/landing/Below"));

export default function Landing() {
  const { source, ready } = useDataSource();
  const hero = useRef<HTMLElement>(null);
  const [plans, setPlans] = useState<PricingPlan[] | null>(null);

  useEffect(() => {
    document.title = "Notary: no certificate, no money moves";
  }, []);

  // The cfo.ai plan: priced plans or nothing (the section and its nav link stay hidden).
  useEffect(() => {
    const controller = new AbortController();
    loadEconomicsPlan(controller.signal).then(
      (raw) => !controller.signal.aborted && setPlans(pricingPlans(raw)),
      () => !controller.signal.aborted && setPlans(null),
    );
    return () => controller.abort();
  }, []);

  // "See it work": VITE_NOTARY_VIDEO_URL when set (no video exists today), else How it works.
  const seeIt = seeItWorkHref(import.meta.env.VITE_NOTARY_VIDEO_URL as string | undefined);

  return (
    <div className="landing theme-light">
      <a className="l-skip" href="#landing-main">
        Skip to content
      </a>
      <Nav showPricing={!!plans} />
      <main id="landing-main" className="l-main">
        <Hero heroRef={hero} source={source} seeIt={seeIt} />
        <Suspense fallback={<div className="l-below-pending" />}>
          <Below source={source} ready={ready} plans={plans} />
        </Suspense>
      </main>
    </div>
  );
}

// Data for the landing page (`/`). Every number the landing shows is derived here from data the
// data layer (src/data) verified: run bundles (hash-checked), timelines (tied to their bundle),
// certificates (seals recomputed) and the optional cfo.ai plan (public/economics.json). Nothing
// here fetches and no result is typed by hand. The only literals are copy (step and feature
// sentences, the "Built with" credits) and links.
import { RequestTypeSchema } from "../../core/src/schema";
import type { Certificate, Decision, FixtureIndex, RequestType, Revocation, RunBundle } from "../../core/src/schema";
import { label, scenarioKey, type CertificateWorld } from "./data";
import { GITHUB_URL } from "./lib/site";
import { verifyEconomicsFile } from "./data/economics";

/** The repository, linked from the nav and the footer (one site-wide constant, AUDIT H-44). */
export { GITHUB_URL };

/** Credits line ("Built with") and the chat showcase's chips. Text only; no status is claimed. */
export const BUILT_WITH = ["neatlogs", "Entire", "cfo.ai", "Crustdata", "Dodo Payments", "AWS Bedrock"] as const;

/** The Run page for one run (the dashboard reads `?run=`). */
export const runHref = (runId: string) => `/app/run?run=${encodeURIComponent(runId)}`;

/** What the hero mockup's address bar shows: where this app is actually served, never a made-up domain. */
export const mockupAddress = (origin: string) => `${origin.replace(/\/+$/, "")}/app/run`;

// --------------------------------------------------------------------------- navigation

export type NavLink = { label: string; href: string; external?: boolean };

/** The documentation, served by the app itself at /docs. */
export const DOCS_HREF = "/docs";

/** Center links of the nav. Pricing only when the pricing section is shown. */
export function navLinks(showPricing: boolean): NavLink[] {
  return [
    { label: "How it works", href: "#how" },
    { label: "Features", href: "#features" },
    { label: "Chat", href: "#chat" },
    ...(showPricing ? [{ label: "Pricing", href: "#pricing" }] : []),
    { label: "Docs", href: DOCS_HREF },
    { label: "GitHub", href: GITHUB_URL, external: true },
  ];
}

/** In-app routes ("/docs", "/app") go through the router; hash and external links stay plain anchors. */
export const isRoute = (l: NavLink) => !l.external && l.href.startsWith("/");

export const FOOTER_LINKS: readonly NavLink[] = [
  { label: "GitHub", href: GITHUB_URL, external: true },
  { label: "Dashboard", href: "/app" },
  { label: "Docs", href: DOCS_HREF },
];

// --------------------------------------------------------------------------- copy

/**
 * How it works, in three columns. Copy only, matching what packages/core does (README "How it
 * works"): no counts, no provider names, no claim that code makes every decision (AUDIT H-36).
 */
export const HOW_STEPS = [
  {
    id: "predict",
    title: "Predict, then test",
    body: "Every probe commits its prediction before the API is called. When the response disagrees, the mismatch is on the record.",
    wash: "sky",
  },
  {
    id: "challenge",
    title: "Challenge",
    body: "The Reflector explains each mismatch; the Adversary reads the raw records and tries to knock the belief down.",
    wash: "lavender",
  },
  {
    id: "certify",
    title: "Certify & enforce",
    body: "Beliefs that survive become sealed certificates. The Guard lets covered money actions through and holds the rest.",
    wash: "mint",
  },
] as const;

export type HowStepId = (typeof HOW_STEPS)[number]["id"];

export type FeatureKey = "certificates" | "held" | "chat" | "revocation";

export const FEATURES: readonly { key: FeatureKey; n: string; title: string; body: string; wash: string }[] = [
  {
    key: "certificates",
    n: "01",
    title: "Certificates",
    body: "Every belief that survives testing and review becomes a sha256-sealed certificate, with the scope it was tested in and the probes behind it.",
    wash: "lavender",
  },
  {
    key: "held",
    n: "02",
    title: "Held actions",
    body: "A refund that depends on a claim without a certificate waits for a person, evidence attached. Approve or reject it from the dashboard.",
    wash: "peach",
  },
  {
    key: "chat",
    n: "03",
    title: "Notary Chat",
    body: "Ask about a certificate, a run or a held refund. Notary Chat answers from the records, shows every lookup it makes and cites its sources.",
    wash: "mint",
  },
  {
    key: "revocation",
    n: "04",
    title: "Revocation",
    body: "When later evidence contradicts a certificate, Notary revokes it, retires its guards and holds the actions that relied on it.",
    wash: "sky",
  },
];

// --------------------------------------------------------------------------- run pairing

type PairEntry = {
  runId: string;
  kind: string;
  variant: string;
  sample: boolean;
  startedAt: string;
};

export type LandingView = {
  /** The development-only fixture view (`?fixtures=1`): fixture runs only. Default: real runs only. */
  fixtures?: boolean;
};

/**
 * The newest naive/guarded queue-run pair of the visible cohort: real runs only, or fixture runs
 * only under `?fixtures=1`. There is no fallback from one cohort to the other: with no real run the
 * pair is empty and the landing says so. The naive side must come from the guarded run's world
 * (same scenario key), so the landing never compares two different worlds.
 */
export function landingResults<T extends PairEntry>(all: readonly T[], view: LandingView = {}) {
  const fixtures = !!view.fixtures;
  const cohort = all
    .filter((b) => b.sample === fixtures && b.kind === "run")
    .sort((a, b) => b.startedAt.localeCompare(a.startedAt));
  const guarded = cohort.find((b) => b.variant === "guarded");
  const naive = guarded
    ? cohort.find((b) => b.variant === "naive" && scenarioKey(b.runId) === scenarioKey(guarded.runId))
    : cohort.find((b) => b.variant === "naive");
  return { sample: fixtures, naive, guarded };
}

/** The fixture naive/guarded pair (the `?fixtures=1` view). */
export function fixturePair<T extends PairEntry>(all: readonly T[]) {
  return landingResults(all, { fixtures: true });
}

/**
 * The pair the Proof section, the hero preview and the feature cards show: the visible cohort's
 * newest pair, possibly incomplete. Never a fixture run in the default view, never one real side
 * and one fixture side. `visible` counts the visible cohort's runs, so the page can tell "nothing
 * yet" from "no complete pair yet".
 */
export function proofPair<T extends PairEntry>(all: readonly T[], view: LandingView = {}) {
  const pair = landingResults(all, view);
  const visible = all.filter((b) => b.sample === !!view.fixtures).length;
  return { ...pair, visible };
}

/** The landing's empty state when no run is published: the two commands that record and publish one. */
export const NO_RUNS_YET = {
  title: "No runs yet",
  body: "Notarize a real API, then publish the run. Every number on this page comes from it.",
  commands: ["pnpm notary notarize --tool crustdata", "pnpm notary export"],
} as const;

/**
 * The fixture scenario whose certificate export records a revocation (today: change-api), and one
 * of its source runs (to ask the data layer for that world's certificates). Undefined when no
 * published scenario records one.
 */
export function revocationScenario(index: FixtureIndex | null): { scenario: string; runId: string } | undefined {
  const s = index?.scenarios.find((x) => x.overall.revoked > 0 && x.sourceBundles.length > 0);
  return s ? { scenario: s.scenario, runId: s.sourceBundles[0]! } : undefined;
