    const ro = new ResizeObserver(([entry]) => {
      if (entry) el.style.setProperty("--shot-scale", String(entry.contentRect.width / SHOT_WIDTH));
    });
    ro.observe(el);
    return () => ro.disconnect();
  }, []);
  useEffect(() => {
    if (!idle) return;
    let live = true;
    replayPair(replay).then(
      (p) => {
