          { scale: 0.96, y: 0 },
          {
            scale: 1,
            y: -48,
            ease: "none",
            scrollTrigger: { trigger: heroRef.current, start: "top top", end: "bottom top", scrub: true },
          },
        );
      });
    },
    { scope: heroRef },
  );

  return (
    <section ref={heroRef} className="l-hero sky" aria-labelledby="hero-title" data-nav-dark>
      <div className="l-hero-copy">
