  useGSAP(
    () => {
      const mm = gsap.matchMedia();
      mm.add(MOTION_OK, () => {
        revealTitle(root.current!.querySelector(".l-h2"));
        drawStrokes(gsap.utils.toArray<SVGGeometryElement>(".l-draw", root.current), root.current!.querySelector(".l-chat-stage"), 1.1);
