79	const clip = (s: string, n: number) => (s.length > n ? `${s.slice(0, n - 1)}…` : s);
80	const escapeRe = (s: string) => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
81	const mentions = (text: string, term: string) =>
82	  term.length > 1 && new RegExp(`(^|[^A-Za-z0-9_-])${escapeRe(term)}($|[^A-Za-z0-9_-])`).test(text);
83	const pct = (x: number) => `${(x * 100).toFixed(1)}%`;
