85	/**
86	 * Explain answers are one long paragraph: split into sentences at ". " (code-built sentences may
87	 * start with a lowercase claim id), never inside a quotation and never inside "P(holds)=0.62".
88	 */
89	export function sentences(text: string): string[] {
90	  const out: string[] = [];
91	  let start = 0;
92	  let quoted = false;
93	  for (let i = 0; i < text.length; i++) {
94	    const ch = text[i]!;
95	    const endsHere = /\s/.test(text[i + 1] ?? "") || i + 1 === text.length;
96	    if (ch === '"') {
97	      quoted = !quoted;
98	      // A closing quote right after the punctuation ends the sentence too.
99	      if (!quoted && /[.!?]/.test(text[i - 1] ?? "") && endsHere) {
100	        out.push(text.slice(start, i + 1).trim());
101	        start = i + 1;
102	      }
103	    } else if (!quoted && /[.!?]/.test(ch) && endsHere) {
104	      out.push(text.slice(start, i + 1).trim());
105	      start = i + 1;
106	    }
107	  }
108	  out.push(text.slice(start).trim());
109	  return out.filter(Boolean);
110	}
