112	/** "FIXTURE scenario x (…): rest" → ["FIXTURE scenario x (…)", "rest"]. */
113	function splitDisclosure(answer: string): [string | undefined, string] {
114	  const m = /^((?:FIXTURE|SYNTHETIC)[^:]*\)):\s*/.exec(answer);
115	  return m ? [m[1], answer.slice(m[0].length)] : [undefined, answer];
116	}
