120	class Turn {
121	  readonly events: ChatEvent[] = [];
122	  private steps = 0;
123	  private readonly citables = new Map<string, Citable>();
124	  private readonly numbers = new Map<string, number>();
125	  private readonly started: number;
126	
127	  constructor(
128	    private readonly onEvent: (e: ChatEvent) => void,
129	    private readonly opts: Required<Pick<ReplayChatOptions, "timers" | "now">> & { pace: ReplayChatOptions["pace"] },
130	    private readonly signal?: AbortSignal,
131	  ) {
132	    this.started = opts.now();
133	  }
134	
135	  private check() {
136	    if (this.signal?.aborted) throw new Aborted();
137	  }
138	
139	  emit(e: ChatEvent) {
140	    this.check();
141	    this.events.push(e);
142	    this.onEvent(e);
143	  }
144	
145	  async pause(kind: "step" | "chunk") {
146	    const pace = this.opts.pace === "instant" ? 0 : (this.opts.pace ?? DEFAULT_PACE)[kind === "step" ? "stepMs" : "chunkMs"];
147	    if (pace > 0)
148	      await new Promise<void>((resolve) => {
149	        const handle = this.opts.timers.set(() => {
150	          this.signal?.removeEventListener("abort", stop);
151	          resolve();
152	        }, pace);
153	        const stop = () => {
154	          this.opts.timers.clear(handle);
155	          resolve();
156	        };
157	        this.signal?.addEventListener("abort", stop, { once: true });
158	      });
159	    this.check();
160	  }
161	
162	  async note(text: string) {
163	    this.emit({ type: "note", text: clip(text, 200), source: "replay" });
164	    await this.pause("step");
165	  }
166	
167	  async step(tool: ChatToolName, title: string, input: string, run: () => Promise<StepOutcome>): Promise<StepOutcome> {
168	    const id = `s${++this.steps}`;
169	    this.emit({ type: "step_started", id, tool, title, input: clip(input, 160) });
170	    const t0 = this.opts.now();
171	    let outcome: StepOutcome;
172	    try {
173	      outcome = await run();
174	    } catch (e) {
175	      if (e instanceof Aborted || this.signal?.aborted) throw new Aborted();
176	      outcome = { status: "error", output: e instanceof Error ? clip(e.message, 200) : "The step failed." };
177	    }
178	    const durationMs = Math.max(0, Math.round(this.opts.now() - t0));
179	    this.emit({
180	      type: "step_finished",
181	      id,
182	      status: outcome.status,
183	      durationMs,
184	      costUsd: null,
185	      output: clip(outcome.output, 240),
186	      ...(outcome.data !== undefined ? { data: outcome.data } : {}),
187	      ...(outcome.fix ? { fix: outcome.fix } : {}),
188	    });
189	    for (const c of outcome.citables ?? []) {
190	      const key = `${c.type}:${c.id}`;
191	      if (!this.citables.has(key)) this.citables.set(key, { ...c, stepId: id });
192	    }
193	    await this.pause("step");
194	    return outcome;
195	  }
196	
197	  get stepCount() {
198	    return this.steps;
199	  }
200	
201	  /** "[n]" markers for these records (by "<type>:<id>"); unknown keys are skipped, never invented. */
202	  cite(...keys: string[]): string {
203	    const out: number[] = [];
204	    for (const key of keys) {
205	      if (!this.citables.has(key)) continue;
206	      if (!this.numbers.has(key)) this.numbers.set(key, this.numbers.size + 1);
207	      const n = this.numbers.get(key)!;
208	      if (!out.includes(n)) out.push(n);
209	    }
210	    return out
211	      .sort((a, b) => a - b)
212	      .map((n) => `[${n}]`)
213	      .join("");
214	  }
215	
216	  /** Markers for every record of this turn the sentence names (by id terms). */
217	  citeMentions(sentence: string, limit = 3): string {
218	    const keys = [...this.citables].filter(([, c]) => c.terms.some((t) => mentions(sentence, t))).map(([k]) => k);
219	    return this.cite(...keys.slice(0, limit));
220	  }
221	
222	  hasCitable(key: string) {
223	    return this.citables.has(key);
224	  }
225	
226	  async answer(markdown: string): Promise<void> {
227	    // Chunks of a few words, so the answer streams like the live one.
228	    const parts = markdown.match(/\S+\s*|\s+/g) ?? [];
229	    for (let i = 0; i < parts.length; i += 4) {
230	      this.emit({ type: "text_delta", text: parts.slice(i, i + 4).join("") });
231	      if (i + 4 < parts.length) await this.pause("chunk");
232	    }
233	    const items: ChatCitation[] = [...this.numbers]
234	      .sort((a, b) => a[1] - b[1])
235	      .map(([key, n]) => {
236	        const { terms: _t, ...c } = this.citables.get(key)!;
237	        return { ...c, n, valid: true };
238	      });
239	    this.emit({ type: "citations", items });
240	    this.emit({
241	      type: "done",
242	      costUsd: null,
243	      tokens: { input: 0, output: 0 },
244	      steps: this.steps,
245	      durationMs: Math.max(0, Math.round(this.opts.now() - this.started)),
246	      mode: "replay",
247	    });
248	  }
249	}
