310	export class ReplayChat implements ChatSource {
311	  private readonly store: ChatStore;
312	  private readonly timers: Timers;
313	  private readonly pace: ReplayChatOptions["pace"];
314	  private readonly now: () => number;
315	  private readonly clock: () => Date;
316	  private readonly newId: () => string;
