318	
319	  constructor(
320	    private readonly data: ReplayChatData,
321	    opts: ReplayChatOptions = {},
322	  ) {
323	    this.store = opts.store ?? sessionChatStore();
324	    this.timers = opts.timers ?? realTimers;
325	    this.pace = opts.pace;
326	    this.now = opts.now ?? (() => (globalThis.performance ?? Date).now());
