359	
360	  /** The world a conversation answers from (pinned run), for the page's label. */
361	  async conversationWorld(id: string): Promise<{ runId: string; world: WorldKey; label: string } | undefined> {
362	    const runId = this.store.load().find((c) => c.conversation.id === id)?.runId;
363	    if (!runId) return undefined;
364	    try {
365	      const b = await this.data.getRun(runId);
366	      const key = worldKeyOf(b);
367	      return { runId, world: key, label: worldLabel(key) };
368	    } catch {
369	      return undefined;
370	    }
371	  }
372	
373	  private update(id: string, fn: (c: StoredConversation) => StoredConversation) {
374	    this.store.save(this.store.load().map((c) => (c.conversation.id === id ? fn(c) : c)));
375	  }
376	
377	  async sendMessage(
378	    conversationId: string,
379	    content: string,
380	    onEvent: (e: ChatEvent) => void,
381	    signal?: AbortSignal,
382	  ): Promise<void> {
383	    const body = SendMessageBodySchema.safeParse({ content });
384	    if (!body.success) {
385	      onEvent({ type: "error", message: "Type a question (at most 4000 characters)." });
386	      return;
387	    }
388	    const stored = this.store.load().find((c) => c.conversation.id === conversationId);
389	    if (!stored) {
390	      onEvent({ type: "error", message: "This conversation is not in this tab's replay history.", fix: "Start a new chat." });
391	      return;
392	    }
393	    const question = body.data.content;
394	    const at = () => this.clock().toISOString();
395	    const userMessage: ChatMessage = { id: this.newId(), conversationId, role: "user", content: question, createdAt: at() };
396	    const pinned = stored.runId ?? this.runId;
397	    this.update(conversationId, (c) => ({
398	      ...c,
399	      runId: pinned,
400	      conversation: { ...c.conversation, title: c.messages.length ? c.conversation.title : clip(question.replace(/\s+/g, " "), 60), updatedAt: at() },
401	      messages: [...c.messages, userMessage],
402	    }));
403	    const previous = [...stored.messages].reverse().find((m) => m.role === "assistant")?.events?.find((e) => e.type === "citations");
404	    const turn = new Turn(onEvent, { timers: this.timers, now: this.now, pace: this.pace }, signal);
405	    let text = "";
406	    const record = (e: ChatEvent) => {
407	      if (e.type === "text_delta") text += e.text;
408	    };
409	    try {
410	      const world = await this.loadWorld(pinned, signal);
411	      if (!world) {
412	        turn.emit({ type: "error", message: "No published run to answer from.", fix: "Publish verified exports with `pnpm notary export`." });
413	      } else {
414	        await this.answer(turn, question, world, previous?.type === "citations" ? previous.items : undefined);
415	      }
416	    } catch (e) {
417	      if (!(e instanceof Aborted) && !signal?.aborted)
418	        try {
419	          turn.emit({ type: "error", message: e instanceof Error ? e.message : String(e) });
420	        } catch {
421	          // aborted while reporting
422	        }
423	    }
424	    for (const e of turn.events) record(e);
425	    const assistant: ChatMessage = {
426	      id: this.newId(),
427	      conversationId,
428	      role: "assistant",
429	      content: text,
430	      events: turn.events,
431	      createdAt: at(),
432	    };
433	    this.update(conversationId, (c) => ({ ...c, conversation: { ...c.conversation, updatedAt: at() }, messages: [...c.messages, assistant] }));
434	  }
