436	  // ------------------------------------------------------------------------------ world
437	
438	  private async loadWorld(runId: string | undefined, signal?: AbortSignal): Promise<World | undefined> {
439	    const entries = (await this.data.listRuns(signal)).filter((r): r is Extract<RunEntry, { state: "finished" }> => r.state === "finished");
440	    if (!entries.length) return undefined;
441	    const bundles = (await Promise.all(entries.map((e) => this.data.getRun(e.runId, signal)))).sort(byNewest);
442	    const selected =
443	      bundles.find((b) => b.runId === runId) ?? bundles.find((b) => !b.sample) ?? bundles[0]!;
444	    const key = worldKeyOf(selected);
445	    const runs = bundles.filter((b) => worldKeyOf(b) === key);
446	    let certificates: Certificate[] = [];
447	    let noCertificates: NoCertificate[] = [];
448	    try {
449	      const cw = await this.data.certificates(entryOfBundle(selected), signal);
450	      // Only a certificate world that is provably this world (never another scenario's).
451	      if (cw.report && cw.world === key) {
452	        certificates = cw.tools.flatMap((t) => t.certificates);
453	        noCertificates = cw.tools.flatMap((t) => t.noCertificates);
454	      }
455	    } catch {
456	      // No certificates for this world: certificate steps say so.
457	    }
458	    let explain: ExplainAnswer[] = [];
459	    try {
460	      const file = await this.data.explain(signal);
461	      const worlds = worldIndex(bundles);
462	      explain = (file?.answers ?? []).filter((a) => answerWorld(a, worlds) === key);
463	    } catch {
464	      // Explain answers withheld: answers use record facts only.
465	    }
466	    return { key, label: worldLabel(key), runs, selected, certificates, noCertificates, explain };
467	  }
468	
469	  private async timeline(runId: string): Promise<TimelineEvent[] | undefined> {
470	    try {
471	      return await this.data.getTimeline(runId);
472	    } catch (e) {
473	      if (e instanceof TimelineMissingError) return undefined;
474	      throw e;
475	    }
476	  }
477	
478	  // ----------------------------------------------------------------------------- answer
479	
480	  private async answer(turn: Turn, question: string, world: World, previous?: ChatCitation[]) {
481	    const claimIds = [...new Set([...world.certificates.map((c) => c.claimId), ...world.noCertificates.map((c) => c.claimId)])];
482	    const route = routeQuestion(question, { runIds: world.runs.map((r) => r.runId), claimIds, previous });
483	    const blocks: string[] = [];
484	    if (world.key !== "real") blocks.push("*Answering from recorded scenario runs, not live data.*");
485	    if (!route.intents.length) {
486	      await turn.note(`Nothing in the question matched a recorded record of ${world.label}; listing what is recorded.`);
487	      await this.listRuns(turn, world);
488	      blocks.push(REPLAY_NO_MATCH);
489	      return turn.answer(blocks.join("\n\n"));
490	    }
491	    await turn.note(`Matched ${route.matched.join(", ")}; reading ${world.label}.`);
492	    for (const intent of await this.expand(route.intents, world)) {
493	      const md = await this.run(turn, intent, world);
494	      if (md) blocks.push(md);
495	    }
496	    return turn.answer(blocks.join("\n\n"));
497	  }
498	
499	  /** Follow-ups become concrete intents: the cited record decides which. */
500	  private async expand(intents: Intent[], world: World): Promise<Intent[]> {
501	    const out: Intent[] = [];
502	    for (const i of intents) {
503	      if (i.kind !== "followup") {
504	        out.push(i);
505	        continue;
506	      }
507	      const c = i.citation;
508	      if (c.type === "certificate") out.push({ kind: "certificate", certId: c.id });
509	      else if (c.type === "approval") out.push({ kind: "approvals", approvalId: c.id });
510	      else if (c.type === "run") out.push({ kind: "runs", runId: c.id });
511	      else if (c.type === "run_event") {
512	        const [runId, seq] = [c.id.slice(0, c.id.lastIndexOf("#")), Number(c.id.slice(c.id.lastIndexOf("#") + 1))];
513	        const ev = world.runs.some((r) => r.runId === runId) ? (await this.timeline(runId))?.find((e) => e.seq === seq) : undefined;
514	        const requestId = ev?.type === "decision" ? (ev.data?.requestId as string | undefined) : undefined;
515	        const claimId = ev?.data?.claimId as string | undefined;
516	        if (requestId) out.push({ kind: "why_held", requestId, runId });
517	        else if (claimId) out.push({ kind: "certificate", claimId });
518	        else out.push({ kind: "runs", runId });
519	      }
520	    }
521	    // De-duplicate (a follow-up may repeat a keyword intent).
522	    return out.filter((x, idx) => out.findIndex((y) => JSON.stringify(y) === JSON.stringify(x)) === idx);
523	  }
524	
525	  private run(turn: Turn, intent: Intent, world: World): Promise<string | undefined> {
526	    switch (intent.kind) {
527	      case "lookup":
528	        return this.lookup(turn, intent.tool, intent.subject);
529	      case "doc":
530	        return this.doc(turn, intent.url);
531	      case "health":
532	        return this.health(turn);
533	      case "why_held":
534	        return this.whyHeld(turn, world, intent.requestId, intent.runId);
535	      case "certificate":
536	        return this.certificate(turn, world, intent);
537	      case "revocations":
538	        return this.revocations(turn, world);
539	      case "run_diff":
540	        return this.runDiff(turn, world);
541	      case "adversary":
542	        return this.adversary(turn, world);
543	      case "approvals":
544	        return this.approvals(turn, world, intent.approvalId, intent.requestId);
545	      case "runs":
546	        return this.runs(turn, world, intent.runId);
547	      case "followup":
548	        return Promise.resolve(undefined);
549	    }
550	  }
