625	  private explainSentences(turn: Turn, answer: ExplainAnswer, keep?: (s: string) => boolean, max = 8): string {
626	    const [disclosure, body] = splitDisclosure(answer.answer);
627	    void disclosure; // the answer opens with the world line instead
628	    const picked = sentences(body).filter((s) => !keep || keep(s)).slice(0, max);
629	    if (!picked.length) return "";
630	    const lines = picked.map((s) => {
631	      const markers = turn.citeMentions(s);
632	      return markers ? `${s} ${markers}` : s;
633	    });
634	    // Short paragraphs of three sentences read better than one block.
635	    const paras: string[] = [];
636	    for (let i = 0; i < lines.length; i += 3) paras.push(lines.slice(i, i + 3).join(" "));
637	    return paras.join("\n\n");
638	  }
