640	  private async whyHeld(turn: Turn, world: World, requestId?: string, runId?: string) {
641	    const guardedFirst = [...world.runs].sort((a, b) => Number(b.variant === "guarded") - Number(a.variant === "guarded"));
642	    const decisionOf = (b: RunBundle) => b.decisions.find((d) => d.requestId === requestId);
643	    let run =
644	      world.runs.find((b) => b.runId === runId) ??
645	      (requestId
646	        ? [world.selected, ...guardedFirst].find((b) => decisionOf(b)?.status === "held") ??
647	          [world.selected, ...guardedFirst].find((b) => decisionOf(b))
648	        : world.selected.decisions.some((d) => d.status === "held")
649	          ? world.selected
650	          : guardedFirst.find((b) => b.decisions.some((d) => d.status === "held")));
651	    if (!run) {
652	      await this.listRuns(turn, world);
653	      return requestId
654	        ? `No recorded run in ${world.label} has a request ${requestId}. ${turn.cite(...world.runs.map((r) => `run:${r.runId}`).slice(0, 2))}`.trim()
655	        : `No recorded run in ${world.label} held anything.`;
656	    }
657	    if (!requestId) {
658	      const { rows } = await this.runEvents(turn, run, "held decisions", (e) => e.type === "decision" && e.data?.status === "held");
659	      if (!rows) return `${run.runId} has no published timeline, so its held decisions can't be listed here.`;
660	      if (!rows.length) return `Nothing was held in ${run.runId}. ${turn.cite(`run:${run.runId}`)}`;
661	      const list = rows
662	        .slice(0, MAX_ROWS)
663	        .map((e) => `- ${e.summary} ${turn.cite(`run_event:${e.runId}#${e.seq}`)}`)
664	        .join("\n");
665	      return `${rows.length} decision${rows.length === 1 ? " was" : "s were"} held in ${run.runId}:\n\n${list}\n\nAsk “Why was ${String(rows[0]!.data?.requestId ?? "it")} held?” for the reasons behind one.`;
666	    }
667	    const decision = decisionOf(run)!;
668	    const { rows } = await this.runEvents(turn, run, `the decision for ${requestId}`, (e) => e.type === "decision" && e.recordIds.includes(requestId));
669	    const event = rows?.[0];
670	    const lead = event ? `${event.summary} ${turn.cite(`run_event:${event.runId}#${event.seq}`)}` : `${requestId} in ${run.runId} ended ${decision.status}.`;
671	    if (decision.status !== "held") return `${requestId} was not held in ${run.runId}. ${lead}`;
672	    // The held action, as the approval desk lists it (read-only in replay).
673	    let approval: PendingApproval | undefined;
674	    await turn.step("get_approval", `Opening the held action ${requestId}`, `${run.runId} ${requestId}`, async () => {
675	      const list = await this.data.approvals();
676	      approval = list.pending.find((a) => a.runId === run!.runId && a.decisionId === decision.id);
677	      return approval
678	        ? { status: "ok", output: `Held: ${approval.action} — read-only in replay`, data: { kind: "approval", readOnly: true, ...approvalData(approval) }, citables: [approvalCitable(approval)] }
679	        : { status: "error", output: `No held action is listed for ${requestId} in ${run!.runId}` };
680	    });
681	    // Certificates behind the claims the decision needed (missing beliefs, applied guards).
682	    const claims = new Set<string>([
683	      ...decision.missingBeliefs.map(claimOfBelief),
684	      ...decision.guardsApplied.flatMap((g) => run!.guards.filter((x) => x.id === g).map((x) => claimOfBelief(x.beliefId))),
685	    ]);
686	    const certs = [...claims]
687	      .map((claim) => world.certificates.filter((c) => c.claimId === claim).sort((a, b) => Number(a.status === "revoked") - Number(b.status === "revoked"))[0])
688	      .filter((c): c is Certificate => Boolean(c))
689	      .slice(0, 2);
690	    for (const c of certs) await this.getCertificate(turn, c);
691	    const explain = world.explain.find((a) => a.kind === "why_held" && a.runIds.includes(run!.runId) && a.citations.some((c) => c.kind === "decision" && c.id === decision.id));
692	    const blocks = [lead];
693	    if (explain) blocks.push(this.explainSentences(turn, explain, undefined, 9));
694	    else if (decision.missingBeliefs.length)
695	      blocks.push(`It needed notarized beliefs that were missing: ${decision.missingBeliefs.map((b) => `\`${claimOfBelief(b)}\``).join(", ")}.`);
696	    for (const c of certs) blocks.push(`Certificate for \`${c.claimId}\`: ${c.status}, ${c.verdict.replace(/\.$/, "")}. ${turn.cite(`certificate:${c.id}`)}`);
697	    if (approval)
698	      blocks.push(`The held action is read-only here; approving or rejecting it needs \`pnpm notary serve\` (Approvals page). ${turn.cite(`approval:${approval.id ?? `${approval.runId}:${approval.decisionId}`}`)}`);
699	    if (explain) blocks.push(`*Source: precomputed answer \`${explain.id}\` (notary export --explain).*`);
700	    return blocks.filter(Boolean).join("\n\n");
701	  }
