703	  private async certificate(turn: Turn, world: World, intent: Extract<Intent, { kind: "certificate" }>) {
704	    const { certId, tool } = intent;
705	    let claimId = intent.claimId;
706	    if (certId && !claimId) claimId = world.certificates.find((c) => c.id === certId)?.claimId;
707	    const query = certId ?? claimId ?? tool ?? "all";
708	    let results: Certificate[] = [];
709	    let missing: NoCertificate[] = [];
710	    await turn.step("search_certificates", `Searching certificates for ${query}`, query, async () => {
711	      if (!world.certificates.length && !world.noCertificates.length)
712	        return { status: "ok", output: `No certificates are published for ${world.label}`, data: { kind: "certificates", world: world.key, results: [] } };
713	      const match = (c: { tool: Tool; claimId: string; id?: string }) =>
714	        certId ? c.id === certId : claimId ? c.claimId === claimId : tool ? c.tool === tool : true;
715	      results = world.certificates.filter(match).sort((a, b) => Number(a.status === "revoked") - Number(b.status === "revoked"));
716	      missing = certId ? [] : world.noCertificates.filter(match);
717	      return {
718	        status: "ok",
719	        output: `${results.length} certificate${results.length === 1 ? "" : "s"}${missing.length ? `, ${missing.length} claim${missing.length === 1 ? "" : "s"} without one` : ""}`,
720	        data: {
721	          kind: "certificates",
722	          world: world.key,
723	          results: results.slice(0, MAX_ROWS).map((c) => ({ id: c.id, tool: c.tool, claimId: c.claimId, status: c.status, verdict: c.verdictKind.replace("_", " "), confidence: c.confidence, evidence: c.evidence.length })),
724	          ...(missing.length ? { noCertificates: missing.slice(0, MAX_ROWS).map((n) => ({ claimId: n.claimId, kind: n.kind, reason: n.reason })) } : {}),
725	        },
726	        citables: results.slice(0, MAX_ROWS).map(certCitable),
727	      };
728	    });
729	    const focus = certId || claimId ? results.slice(0, 1) : results.filter((c) => c.status === "active").slice(0, 2);
730	    for (const c of focus) await this.getCertificate(turn, c);
731	    const blocks: string[] = [];
732	    if (!results.length && !missing.length) return `No certificate in ${world.label} matches ${query}.`;
733	    for (const c of focus) {
734	      const n = turn.cite(`certificate:${c.id}`);
735	      blocks.push(
736	        [
737	          `**\`${c.claimId}\`** — certificate \`${c.id}\` is ${c.status}${c.revocation ? ` (revoked ${c.revocation.revokedAt})` : ""}. ${n}`,
738	          `- Verdict: ${c.verdict.replace(/\.$/, "")}, P(doc claim holds) = ${pct(c.confidence)} ${n}`,
739	          `- Docs say: ${clip(c.docsSay, 220)}`,
740	          `- Observed: ${clip(c.observed, 220)}`,
741	          `- Scope: ${clip(c.scope.narrowed?.text ?? c.scope.text, 220)}`,
742	          `- Evidence: ${c.evidence.length} probe${c.evidence.length === 1 ? "" : "s"}`,
743	        ].join("\n"),
744	      );
745	    }
746	    for (const n of missing.slice(0, claimId ? 1 : 3))
747	      blocks.push(`\`${n.claimId}\` has no active certificate (${n.kind.replaceAll("_", " ")}): ${clip(n.reason, 220)}`);
748	    if (!claimId && !certId && results.length > focus.length)
749	      blocks.push(`${results.length - focus.length} more certificate${results.length - focus.length === 1 ? "" : "s"} in the search results above.`);
750	    const knowledge = world.explain.find((a) => a.kind === "tool_knowledge" && (tool ? a.id.endsWith(`:${tool}`) : claimId ? a.id.endsWith(`:${claimId.split(".")[0]}`) : false));
751	    if (knowledge) {
752	      const text = this.explainSentences(turn, knowledge, claimId ? (s) => s.includes(claimId!) : undefined, claimId ? 3 : 4);
753	      if (text) blocks.push(text, `*Source: precomputed answer \`${knowledge.id}\` (notary export --explain).*`);
754	    }
755	    return blocks.join("\n\n");
756	  }
