774	  private async runDiff(turn: Turn, world: World) {
775	    await this.listRuns(turn, world);
776	    const scenario = (id: string) => id.replace(/-(run|notarize)-[a-z]+$/, "");
777	    const pairs = world.runs
778	      .filter((b) => b.kind === "run" && b.variant === "guarded")
779	      .map((g) => ({ guarded: g, naive: world.runs.find((b) => b.kind === "run" && b.variant === "naive" && scenario(b.runId) === scenario(g.runId)) }))
780	      .filter((p): p is { guarded: RunBundle; naive: RunBundle } => Boolean(p.naive));
781	    const pair = pairs.find((p) => p.guarded.runId === world.selected.runId || p.naive.runId === world.selected.runId) ?? pairs[0];
782	    if (!pair) return `${world.label} has no naive and guarded run pair to compare.`;
783	    const changed = pair.guarded.decisions.filter((d) => pair.naive.decisions.find((n) => n.requestId === d.requestId)?.status !== d.status);
784	    const ids = new Set(changed.map((d) => d.requestId));
785	    await this.runEvents(turn, pair.guarded, "decisions that changed status", (e) => e.type === "decision" && e.recordIds.some((r) => ids.has(r)));
786	    const explain = world.explain.find((a) => a.kind === "run_diff" && a.runIds.includes(pair.guarded.runId) && a.runIds.includes(pair.naive.runId));
787	    const blocks = [
788	      `From \`${pair.naive.runId}\` to \`${pair.guarded.runId}\`, ${changed.length} of ${pair.guarded.decisions.length} queue items changed status. ${turn.cite(`run:${pair.naive.runId}`, `run:${pair.guarded.runId}`)}`,
789	    ];
790	    if (explain) blocks.push(this.explainSentences(turn, explain, (s) => !/^\d+ items kept/.test(s), 6), `*Source: precomputed answer \`${explain.id}\` (notary export --explain).*`);
791	    return blocks.join("\n\n");
792	  }
