794	  private async adversary(turn: Turn, world: World) {
795	    await this.listRuns(turn, world);
796	    // "The last run" = the newest run of this world that recorded adversary verdicts.
797	    let chosen: { run: RunBundle; verdicts: TimelineEvent[] } | undefined;
798	    for (const run of world.runs) {
799	      const events = await this.timeline(run.runId);
800	      const verdicts = events?.filter((e) => e.type === "adversary.verdict") ?? [];
801	      if (verdicts.length) {
802	        chosen = { run, verdicts };
803	        break;
804	      }
805	    }
806	    if (!chosen) return `No run in ${world.label} recorded an adversary verdict.`;
807	    const newest = world.runs[0]!;
808	    if (newest.runId !== chosen.run.runId)
809	      await turn.note(`${newest.runId} is newer but recorded no adversary verdicts; using ${chosen.run.runId}.`);
810	    const { rows } = await this.runEvents(turn, chosen.run, "adversary verdicts", (e) => e.type === "adversary.verdict");
811	    const all = rows ?? chosen.verdicts;
812	    const rejected = all.filter((e) => e.data?.verdict !== "uphold");
813	    const models = [...new Set(all.map((e) => (typeof e.data?.model === "string" ? e.data.model : undefined)).filter(Boolean))];
814	    const tally = all.reduce<Record<string, number>>((acc, e) => {
815	      const v = String(e.data?.verdict ?? "unknown");
816	      acc[v] = (acc[v] ?? 0) + 1;
817	      return acc;
818	    }, {});
819	    const blocks = [
820	      `In \`${chosen.run.runId}\` the adversary reviewed ${all.length} belief${all.length === 1 ? "" : "s"}: ${Object.entries(tally).map(([v, n]) => `${v} ×${n}`).join(", ")}${models.length ? ` (model ${models.join(", ")}, as recorded)` : " (model not recorded)"}. ${turn.cite(`run:${chosen.run.runId}`)}`,
821	    ];
822	    if (!rejected.length) blocks.push("It upheld every belief it reviewed: nothing was rejected.");
823	    else
824	      blocks.push(
825	        `It rejected ${rejected.length} (downgraded or narrowed):\n\n${rejected
826	          .slice(0, MAX_ROWS)
827	          .map((e) => `- ${e.summary} ${turn.cite(`run_event:${e.runId}#${e.seq}`)}`)
828	          .join("\n")}`,
829	      );
830	    return blocks.join("\n\n");
831	  }
