842	        output: `${items.length} held action${items.length === 1 ? "" : "s"} in recorded runs (read-only in replay)`,
843	        data: { kind: "approvals", readOnly: true, total: items.length, items: shown.map(approvalData) },
844	        citables: shown.map(approvalCitable),
845	      };
846	    });
847	    const one = items.find((a) => (approvalId && a.id === approvalId) || (requestId && a.requestId === requestId));
848	    if (one) {
849	      await turn.step("get_approval", `Opening the held action ${one.requestId}`, one.id ?? one.decisionId, async () => ({
850	        status: "ok",
851	        output: `Held: ${one.action}`,
