856	    }
857	    if (approvalId) return `Approval ${approvalId} is not a held action of ${world.label}.`;
858	    if (!items.length) return `No action is held in the recorded runs of ${world.label}.`;
859	    const byRun = new Map<string, PendingApproval[]>();
860	    for (const a of items) byRun.set(a.runId, [...(byRun.get(a.runId) ?? []), a]);
861	    return [
862	      `${items.length} action${items.length === 1 ? " is" : "s are"} held in the recorded runs of ${world.label}. In replay they are read-only; \`pnpm notary serve\` shows the live approval desk.`,
863	      [...byRun]
864	        .map(([run, list]) => `- \`${run}\`: ${list.map((a) => `${a.requestId} ${turn.cite(`approval:${a.id ?? `${a.runId}:${a.decisionId}`}`)}`).join(", ")}`)
865	        .join("\n"),
866	    ].join("\n\n");
