869	  private async runs(turn: Turn, world: World, runId?: string) {
870	    await this.listRuns(turn, world);
871	    const run = world.runs.find((r) => r.runId === runId) ?? world.selected;
872	    const { rows } = await this.runEvents(turn, run, "the run's outcome", (e) => e.type === "run.finished" || e.type === "certificate.revoked" || e.type === "certificate.issued");
873	    const finished = rows?.find((e) => e.type === "run.finished");
874	    const held = run.decisions.filter((d) => d.status === "held").length;
875	    const lines = [
876	      `${world.runs.length} run${world.runs.length === 1 ? " is" : "s are"} recorded in ${world.label}: ${world.runs.map((r) => `\`${r.runId}\` (${r.kind}, ${r.variant}) ${turn.cite(`run:${r.runId}`)}`).join(", ")}.`,
877	    ];
878	    lines.push(
879	      finished
880	        ? `\`${run.runId}\`: ${finished.summary} ${turn.cite(`run_event:${finished.runId}#${finished.seq}`)}`
881	        : `\`${run.runId}\` ended ${run.status}${run.decisions.length ? ` with ${held} of ${run.decisions.length} decisions held` : ""}. ${turn.cite(`run:${run.runId}`)}`,
882	    );
883	    return lines.join("\n\n");
884	  }
885	}
