.l-nav {
  position: sticky;
  top: 0;
  z-index: 30;
  height: var(--l-nav-h);
  margin-bottom: calc(-1 * var(--l-nav-h));
  padding-top: 10px;
  color: var(--text);
  transition: color 200ms ease-out;
}
.l-nav::before {
  content: "";
  position: absolute;
  inset: 0 0 -20px;
  z-index: -1;
  opacity: 0;
  -webkit-backdrop-filter: blur(24px);
  backdrop-filter: blur(24px);
  -webkit-mask-image: linear-gradient(180deg, #000 72%, transparent);
  mask-image: linear-gradient(180deg, #000 72%, transparent);
  transition: opacity 200ms ease-out;
  pointer-events: none;
}
.l-nav[data-scrolled]::before {
  opacity: 1;
}
.l-nav[data-tone="light"] {
  color: #ffffff;
}
.l-nav-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  height: 54px;
}
.l-wordmark {
  color: inherit;
  font-family: var(--font-display);
  font-size: 26px;
  font-weight: 400;
  letter-spacing: -0.01em;
  line-height: 1;
  text-decoration: none;
}
.l-nav-links {
  display: none;
}
.l-nav-links ul {
  display: flex;
  gap: 28px;
  margin: 0;
  padding: 0;
  list-style: none;
}
.l-nav-links a {
  color: inherit;
  font-size: 15px;
  font-weight: 500;
  text-decoration: none;
  text-underline-offset: 6px;
  transition: color 150ms ease-out;
}
.l-nav[data-tone="dark"] .l-nav-links a:hover,
.l-nav[data-tone="dark"] .l-nav-links a:focus-visible,
.l-nav[data-tone="dark"] .l-nav-links a[aria-current] {
  color: var(--accent);
}
.l-nav[data-tone="light"] .l-nav-links a {
  color: rgb(255 255 255 / 0.9);
}
.l-nav[data-tone="light"] .l-nav-links a:hover,
.l-nav[data-tone="light"] .l-nav-links a:focus-visible,
.l-nav[data-tone="light"] .l-nav-links a[aria-current] {
  color: #ffffff;
  text-decoration: underline;
  text-decoration-color: rgb(255 255 255 / 0.6);
}
.l-nav[data-tone="light"] :focus-visible {
  outline-color: #ffffff;
}
@media (min-width: 960px) {
  .l-nav-links {
    display: block;
  }
}
/* Black with white text (brand .btn-ink); hover lifts to a lighter black. */
.l-nav-cta {
  min-height: 38px;
  padding: 0 16px;
  font-size: 14px;
  font-weight: 500;
  transition: background-color 150ms ease-out;
}
.l-nav-cta:hover {
  background: #2a3142;
}
.l-btn-lg {
  min-height: 48px;
  padding: 0 22px;
  font-size: 16px;
}

