import { existsSync, readFileSync } from "node:fs";
import { it } from "vitest";
import { PublishedFiles, ReplaySource, memoryChatStore } from "../src/data";
const PUBLIC = new URL("../public/", import.meta.url);
it("print", async () => {
  const files = new PublishedFiles({ base: "/", fetchImpl: (async (i: string) => { const p = new URL(decodeURIComponent(String(i).slice(1)), PUBLIC); return existsSync(p) ? new Response(readFileSync(p), { headers: { "content-type": "application/json" } }) : new Response("", { status: 404 }); }) as unknown as typeof fetch });
  const s = new ReplaySource({ published: files, chat: { store: memoryChatStore(), pace: "instant", fixtures: () => false } });
  for (const q of ["What happened in the last run?", "How much did the runs cost? any pricing?", "What did notarize-crustdata-20261012T011404Z-replay cost?", "What did the last run spend?"]) {
    const c = await s.chat.createConversation(); let t = "";
    await s.chat.sendMessage(c.id, q, (e) => { if (e.type === "text_delta") t += e.text; if (e.type === "error") t += "ERR " + e.message; });
    console.log("Q:", q, "\n", t, "\n-----");
  }
}, 30000);
EOF
